fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn field_type(code:u16)->Result<TiffFieldType,ValueError>{<TiffFieldType as crate::standards::v6_0::subsets::document::io::NativeFieldType>::from_u16(code).map_err(invalid)}
const FLOAT:&[FloatColumn]=&[FloatColumn::Binary32(3)];
const VALUE_TABLES:[(&str,u16,usize);12]=[("tiff_byte_value",1,4),("tiff_ascii_value",2,4),("tiff_short_value",3,4),("tiff_long_value",4,4),("tiff_rational_value",5,5),("tiff_signed_byte_value",6,4),("tiff_undefined_value",7,4),("tiff_signed_short_value",8,4),("tiff_signed_long_value",9,4),("tiff_signed_rational_value",10,5),("tiff_float_value",11,6),("tiff_double_value",12,5)];
fn integer(value:usize)->Result<i64,ValueError>{i64::try_from(value).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"TIFF ordinal exceeds SQLite integer range"))}
fn identity(row:&SqliteRow,columns:usize)->Result<(),ValueError>{if row.rowid<=0||row.values.len()!=columns||row.integer(0)?!=row.rowid{Err(invalid("TIFF entity identity or column shape is invalid"))}else{Ok(())}}
fn tick(control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<(),ValueError>{*count=count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"TIFF traversal count overflow"))?;if *count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;}Ok(())}
fn value_count(value:&TiffValues)->usize{match value{TiffValues::Byte(v)|TiffValues::Undefined(v)=>v.len(),TiffValues::Ascii(v)=>v.len(),TiffValues::Short(v)=>v.len(),TiffValues::Long(v)=>v.len(),TiffValues::Rational(v)=>v.len(),TiffValues::SByte(v)=>v.len(),TiffValues::SShort(v)=>v.len(),TiffValues::SLong(v)=>v.len(),TiffValues::SRational(v)=>v.len(),TiffValues::Float(v)=>v.len(),TiffValues::Double(v)=>v.len()}}
