fn integers(p:&mut RowWriter<'_,'_>,table:&str,tag:i64,values:impl Iterator<Item=i64>)->Result<(),ValueError>{for(ordinal,value)in values.enumerate(){p.insert(table,&[Cell::Integer(tag),Cell::Integer(integer(ordinal)?),Cell::Integer(value)])?;}Ok(())}
fn rationals(p:&mut RowWriter<'_,'_>,table:&str,tag:i64,values:impl Iterator<Item=(i64,i64)>)->Result<(),ValueError>{for(ordinal,(numerator,denominator))in values.enumerate(){p.insert(table,&[Cell::Integer(tag),Cell::Integer(integer(ordinal)?),Cell::Integer(numerator),Cell::Integer(denominator)])?;}Ok(())}


